.darma-loader-darma-b9-elastic-dot { --accent: var(--loader-color, #a855f7); --accent-2: var(--loader-secondary-color, #2dd4bf); width: var(--loader-size, 96px); height: calc(var(--loader-size, 96px) * .3); position: relative; }
.darma-loader-darma-b9-elastic-dot span { position: absolute; top: 50%; left: 0; width: calc(var(--loader-size, 96px) * .24); height: calc(var(--loader-size, 96px) * .24); margin-top: calc(var(--loader-size, 96px) * -.12); border-radius: 50%; background: linear-gradient(90deg, var(--accent), var(--accent-2)); animation: darma-loader-darma-b9-elastic-dot-elastic calc(var(--loader-speed, 1s) * 1.4) cubic-bezier(.5, -0.3, .5, 1.3) infinite; }
@keyframes darma-loader-darma-b9-elastic-dot-elastic { 0% { left: 0; transform: scaleX(1); } 30% { transform: scaleX(1.7) scaleY(.72); } 50% { left: calc(100% - var(--loader-size, 96px) * .24); transform: scaleX(1); } 80% { transform: scaleX(1.7) scaleY(.72); } 100% { left: 0; transform: scaleX(1); } }

